from pathlib import Path
p=Path("src/async-components/views/dialogs/security/ExportE2eKeysDialog.tsx")
s=p.read_text()
s=s.replace('React, { ChangeEvent }','React, { ChangeEvent, createRef }')
s=s.replace('import { KeysStartingWith }', 'import PassphraseField from "../../../../components/views/auth/PassphraseField";\nimport PassphraseConfirmField from "../../../../components/views/auth/PassphraseConfirmField";\nimport { scorePassword } from "../../../../utils/PasswordScorer";\nimport { KeysStartingWith }')
s=s.replace('    private unmounted = false;', '    private unmounted = false;\n    private validating = false;\n    private readonly passphraseRef = createRef<Field>();\n    private readonly confirmationRef = createRef<Field>();')
a=s.index('    private onPassphraseFormSubmit =');b=s.index('    private startExport',a)
s=s[:a]+'    private onPassphraseFormSubmit = async (ev: React.FormEvent): Promise<void> => {\n        ev.preventDefault();\n        if (this.validating || this.state.phase === Phase.Exporting) return;\n        this.validating = true;\n        const { passphrase1, passphrase2 } = this.state;\n        try {\n            const [valid, confirmed] = await Promise.all([\n                this.passphraseRef.current?.validate({ allowEmpty: false }),\n                this.confirmationRef.current?.validate({ allowEmpty: false }),\n            ]);\n            if (this.unmounted || passphrase1 !== this.state.passphrase1 || passphrase2 !== this.state.passphrase2) return;\n            if (!passphrase1) {\n                this.setState({ errStr: _t("Passphrase must not be empty") });\n            } else if (passphrase1 !== passphrase2) {\n                this.setState({ errStr: _t("Passphrases must match") });\n            } else if (!valid || !confirmed || (scorePassword(this.props.matrixClient, passphrase1)?.score ?? 0) < 3) {\n                this.setState({ errStr: _t("Please choose a stronger passphrase") });\n            } else {\n                this.startExport(passphrase1);\n            }\n        } finally {\n            this.validating = false;\n        }\n    };\n\n'+s[b:]
s=s.replace('                this.props.onFinished(true);','                if (!this.unmounted) {\n                    this.setState({ passphrase1: "", passphrase2: "" }, () => this.props.onFinished(true));\n                }')
s=s.replace('        this.props.onFinished(false);','        this.setState({ passphrase1: "", passphrase2: "" }, () => this.props.onFinished(false));')
s=s.replace('                                <Field\n                                    label={_t("Enter passphrase")}','                                <PassphraseField\n                                    fieldRef={this.passphraseRef}\n                                    minScore={3}\n                                    label={_t("Enter passphrase")}')
s=s.replace('                                <Field\n                                    label={_t("Confirm passphrase")}','                                <PassphraseConfirmField\n                                    fieldRef={this.confirmationRef}\n                                    password={this.state.passphrase1}\n                                    label={_t("Confirm passphrase")}')
s=s.replace('(e: ChangeEvent<HTMLInputElement>) =>','(e) =>').replace('this.onPassphraseChange(e,','this.onPassphraseChange(e as ChangeEvent<HTMLInputElement>,')
p.write_text(s)
